import {createFeature,moveFeature,reorder,decode,encode,History,blankWorld,restoreWorld} from './model.js';
import {icon,path,renderFeature,backdrop,esc} from './render.js';
const $=id=>document.getElementById(id),KEY='world-atlas-v1';
let state=blankWorld(),saveBlocked=false;
try{const raw=localStorage.getItem(KEY);state=await restoreWorld(raw);}catch{saveBlocked=true;}
const history=new History(state);let selected=null,tool='select',gesture=null,space=false,showLayers=false,toastTimer;
const svg=$('map'),view=$('viewport');let camera={x:0,y:0,k:1},baseScale=1;
const toolInfo=[['select','Select & move','V'],['pan','Pan the map','H'],['river','River','R'],['forest','Forest','F'],['mountain','Mountains','M'],['road','Road','D'],['settlement','Village','B']];
const tips={select:'Click a feature to discover its story. Drag it to a new home.',pan:'Drag anywhere to explore your world. Scroll to zoom in for a closer look.',river:'Drag across the map to draw a winding river. Release to finish.',road:'Drag to draw a road connecting your favourite places.',forest:'Click the map to plant a little woodland. Adjust its size after placing.',mountain:'Click the map to raise a mountain range. Every peak has a story.',settlement:'Click the map to found a village. Give it a name and a little lore.'};
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function save(){if(saveBlocked){$('save-status').textContent='Save paused · export a backup';$('save-status').classList.add('error');return;}try{localStorage.setItem(KEY,encode(state));$('save-status').textContent='Saved on this browser';$('save-status').classList.remove('error');}catch{$('save-status').textContent='Save failed · export a backup';$('save-status').classList.add('error');}}
function commit(){history.push(state);save();updateHistory();renderLayers();}
function updateHistory(){$('undo').disabled=!history.canUndo;$('redo').disabled=!history.canRedo;}
function chooseTool(next){tool=next;svg.dataset.tool=next;document.querySelectorAll('.tool').forEach(b=>{b.classList.toggle('active',b.dataset.tool===next);b.setAttribute('aria-pressed',b.dataset.tool===next)});$('tool-tip').textContent=tips[next];$('interaction-hint').textContent=toolInfo.find(t=>t[0]===next)[1].toUpperCase();renderMap();}
function renderMap(){$('features').innerHTML=state.features.map(f=>renderFeature(f,f.id===selected)).join('');const f=state.features.find(f=>f.id===selected);$('handles').innerHTML=f?.visible&&['river','road'].includes(f.type)&&tool==='select'?f.points.map((p,i)=>`<circle class="vertex" data-vertex="${i}" cx="${p[0]}" cy="${p[1]}" r="${4/camera.k}"/>`).join(''):'';}
function select(id){selected=id;renderMap();renderPanel();renderLayers();}
function renderPanel(){const f=state.features.find(f=>f.id===selected);if(!f){$('feature-panel').innerHTML=`<div class="empty-illustration"><svg viewBox="0 0 140 130" aria-hidden="true"><path d="M15 38L48 23 90 38 123 23 119 102 87 116 47 101 15 115Z" fill="#eeefdd" stroke="#9bab88" stroke-width="1.5"/><path d="M48 23l-1 78m43-63l-3 78" stroke="#b5bf9e" stroke-width="1.2" stroke-dasharray="4 4"/><path d="M31 86q15-35 40-22t35-16" fill="none" stroke="#8da985" stroke-width="2" stroke-dasharray="4 4"/><path d="M64 39l-13 22h26Z" fill="#a8b792" stroke="#819274"/><path d="M96 75q-13 0-13 12c0 10 13 23 13 23s13-13 13-23q0-12-13-12" fill="#849970"/><circle cx="96" cy="87" r="4" fill="#f5f3e5"/></svg></div><h2 class="empty-title">Somewhere, a story<br>is waiting.</h2><p class="empty-copy">Select a place on the map to give it a name, a story, and a little more life.</p><div class="empty-tip">Or pick a tool from your kit<br>and make somewhere new. ↖</div>`;return;}
const line=['river','road'].includes(f.type);$('feature-panel').innerHTML=`<div class="feature-tag">${icon(f.type)} ${f.type==='settlement'?'Village':esc(f.type)}</div><label class="field">PLACE NAME<input id="feature-name" type="text" maxlength="160" value="${esc(f.name)}" placeholder="Give this place a name"></label><label class="field">ITS STORY<textarea id="feature-lore" maxlength="6000" placeholder="What makes this place special?">${esc(f.lore)}</textarea></label><label class="field">${line?'STROKE WIDTH':'FEATURE SIZE'}<input id="feature-size" type="range" min="${line?2:.5}" max="${line?18:3}" step="${line?1:.05}" value="${f.size}"></label><div class="appearance"><label for="feature-color">Ink colour</label><input id="feature-color" type="color" value="${f.color}"></div><label class="checkbox"><input id="feature-label" type="checkbox" ${f.label?'checked':''}>Show name on map</label><label class="checkbox"><input id="feature-visible" type="checkbox" ${f.visible?'checked':''}>Visible on map</label><div class="stacking"><button id="send-back">↓ Send back</button><button id="bring-front">↑ Bring forward</button></div><p class="edit-note">${line?'Drag the points on your selected path to reshape it.':'Drag this feature on the map to move it.'} Changes save automatically.</p><button class="delete" id="delete-feature">Remove this ${f.type==='settlement'?'village':f.type}</button>`;
for(const [id,prop]of [['feature-name','name'],['feature-lore','lore'],['feature-size','size'],['feature-color','color'],['feature-label','label'],['feature-visible','visible']]){const input=$(id);input.addEventListener('input',()=>{const feature=state.features.find(o=>o.id===selected);feature[prop]=input.type==='checkbox'?input.checked:prop==='size'?Number(input.value):input.value;renderMap();save();});input.addEventListener('change',()=>commit());}
$('send-back').onclick=()=>stack(f.id,-1);$('bring-front').onclick=()=>stack(f.id,1);$('delete-feature').onclick=remove;
$('send-back').disabled=state.features[0]?.id===f.id;$('bring-front').disabled=state.features.at(-1)?.id===f.id;
}
function renderLayers(){$('layer-count').textContent=state.features.length;$('layers').innerHTML=[...state.features].reverse().map((f,i)=>`<div class="layer-row ${selected===f.id?'selected':''}"><button class="eye" data-visibility="${esc(f.id)}" title="${f.visible?'Hide':'Show'} ${esc(f.name)}" aria-label="${f.visible?'Hide':'Show'} ${esc(f.name)}">${f.visible?'◉':'○'}</button><button class="layer-name" data-select="${esc(f.id)}">${esc(f.name||'Unnamed '+f.type)}</button><div class="layer-arrows"><button data-order="1" data-layer="${esc(f.id)}" aria-label="Bring ${esc(f.name)} forward" ${i===0?'disabled':''}>▲</button><button data-order="-1" data-layer="${esc(f.id)}" aria-label="Send ${esc(f.name)} back" ${i===state.features.length-1?'disabled':''}>▼</button></div></div>`).join('')||'<p class="layer-help">A fresh page. Add your first feature from the toolbox.</p>';}
function stack(id,d){state.features=reorder(state.features,id,d);commit();renderMap();renderPanel();}
function remove(){if(!selected)return;state.features=state.features.filter(f=>f.id!==selected);selected=null;commit();renderMap();renderPanel();toast('Feature removed. Undo will bring it back.');}
function renderAll(){renderMap();renderPanel();renderLayers();$('world-title').value=state.title;updateHistory();}
function travel(dir){state=dir==='undo'?history.undo():history.redo();if(!state.features.some(f=>f.id===selected))selected=null;save();renderAll();}
function applyCamera(){view.setAttribute('transform',`translate(${camera.x} ${camera.y}) scale(${camera.k})`);$('zoom-level').textContent=Math.round(camera.k/baseScale*100)+'%';}
function fit(){const w=svg.clientWidth,h=svg.clientHeight;camera.k=Math.max(.15,Math.min(w/1100,h/900));baseScale=camera.k;camera.x=w/2-630*camera.k;camera.y=h/2-435*camera.k;applyCamera();renderMap();}
function zoom(factor,cx=svg.clientWidth/2,cy=svg.clientHeight/2){const next=Math.max(baseScale*.4,Math.min(baseScale*5,camera.k*factor));const ratio=next/camera.k;camera.x=cx-(cx-camera.x)*ratio;camera.y=cy-(cy-camera.y)*ratio;camera.k=next;applyCamera();renderMap();}
function local(e){const b=svg.getBoundingClientRect();return [e.clientX-b.left,e.clientY-b.top];}
function world(e){const [x,y]=local(e);return [(x-camera.x)/camera.k,(y-camera.y)/camera.k];}
function finish(e,cancel=false){if(!gesture||e.pointerId!==gesture.pointerId)return;const g=gesture;gesture=null;$('draft').innerHTML='';if(cancel){if(g.original){state.features=state.features.map(f=>f.id===g.original.id?g.original:f);renderMap();}return;}
if(g.kind==='draw'){if(g.points.length>1){const f=createFeature(g.tool,g.points);state.features.push(f);selected=f.id;commit();renderAll();chooseTool('select');toast('A new '+(f.type==='river'?'river':'road')+'. Give it a name and a story.');}}
if(g.kind==='move'||g.kind==='vertex'){commit();renderPanel();}if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);}
svg.addEventListener('pointerdown',e=>{if(gesture||![0,1].includes(e.button))return;svg.focus({preventScroll:true});const p=world(e);const pan=space||tool==='pan'||e.button===1;const id=e.target.closest('[data-id]')?.dataset.id;const vertex=e.target.dataset.vertex;
if(pan)gesture={kind:'pan',start:local(e),camera:{...camera}};
else if(tool==='select'){if(vertex!==undefined&&selected){const f=state.features.find(o=>o.id===selected);gesture={kind:'vertex',index:Number(vertex),original:structuredClone(f)};}else if(id){select(id);gesture={kind:'move',start:p,original:structuredClone(state.features.find(f=>f.id===id))};}else select(null);}
else if(['river','road'].includes(tool)){gesture={kind:'draw',tool,points:[p]};}
else {const f=createFeature(tool,[p]);state.features.push(f);selected=f.id;commit();chooseTool('select');showTab(false);renderAll();toast('A little place of your own. Add its name and story.');}
if(gesture){gesture.pointerId=e.pointerId;svg.setPointerCapture(e.pointerId);}e.preventDefault();});
svg.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.pointerId)return;const g=gesture,p=world(e);if(g.kind==='pan'){const q=local(e);camera.x=g.camera.x+q[0]-g.start[0];camera.y=g.camera.y+q[1]-g.start[1];applyCamera();}else if(g.kind==='draw'){const last=g.points.at(-1);if(Math.hypot(p[0]-last[0],p[1]-last[1])*camera.k>7){g.points.push(p);$('draft').innerHTML=`<path d="${path(g.points)}" stroke="${g.tool==='river'?'#72a6ae':'#a38a61'}" stroke-width="${g.tool==='river'?7:4}" fill="none" stroke-linecap="round"/>`;}}else if(g.kind==='move'){const m=moveFeature(g.original,p[0]-g.start[0],p[1]-g.start[1]);state.features=state.features.map(f=>f.id===m.id?m:f);renderMap();}else if(g.kind==='vertex'){const f=structuredClone(g.original);f.points[g.index]=p;state.features=state.features.map(o=>o.id===f.id?f:o);renderMap();}});
svg.addEventListener('pointerup',e=>finish(e));svg.addEventListener('pointercancel',e=>finish(e,true));svg.addEventListener('wheel',e=>{e.preventDefault();const [x,y]=local(e);zoom(Math.exp(-e.deltaY*.0015),x,y);},{passive:false});
svg.addEventListener('keydown',e=>{const id=e.target.closest('[data-id]')?.dataset.id;if((e.key==='Enter'||e.key===' ')&&id){e.preventDefault();select(id);showTab(false);}});
function showTab(layers){showLayers=layers;$('layers-panel').hidden=!layers;$('feature-panel').hidden=layers;$('tab-layers').classList.toggle('active',layers);$('tab-feature').classList.toggle('active',!layers);}
$('tools').innerHTML=toolInfo.map(([id,label,key])=>`<button class="tool" data-tool="${id}" title="${label} (${key})" aria-label="${label}" aria-pressed="false">${icon(id)}<span class="tool-label">${label}</span><span class="key">${key}</span></button>`).join('');
$('tools').onclick=e=>{const b=e.target.closest('[data-tool]');if(b)chooseTool(b.dataset.tool);};$('tab-feature').onclick=()=>showTab(false);$('tab-layers').onclick=()=>showTab(true);
$('layers').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.select)select(b.dataset.select);if(b.dataset.visibility){const f=state.features.find(f=>f.id===b.dataset.visibility);f.visible=!f.visible;commit();renderMap();renderPanel();}if(b.dataset.order)stack(b.dataset.layer,Number(b.dataset.order));};
$('undo').onclick=()=>travel('undo');$('redo').onclick=()=>travel('redo');$('fit').onclick=fit;$('zoom-in').onclick=()=>zoom(1.25);$('zoom-out').onclick=()=>zoom(.8);$('toggle-grid').onclick=()=>{const el=$('grid-layer');const visible=el.hasAttribute('hidden');el.toggleAttribute('hidden',!visible);$('toggle-grid').setAttribute('aria-pressed',visible);};
$('world-title').oninput=e=>{state.title=e.target.value;save();};$('world-title').onchange=commit;
$('export').onclick=()=>{const blob=new Blob([encode(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(state.title.replace(/[^a-z0-9]+/gi,'-')||'world')+'.atlas.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('World exported. Keep it somewhere safe.');};
$('import').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10e6)throw Error('Please choose an Atlas file smaller than 10 MB.');const imported=decode(await file.text());state=imported;selected=null;saveBlocked=false;commit();renderAll();fit();toast('Welcome back. Your world has been imported.');}catch(error){toast(error.message||'Could not import this world.');}e.target.value='';};
$('new-world').onclick=()=>$('new-dialog').showModal();$('cancel-new').onclick=()=>$('new-dialog').close();$('confirm-new').onclick=()=>{state=blankWorld();selected=null;saveBlocked=false;commit();renderAll();$('new-dialog').close();toast('A fresh page. Make something wonderful.');};
window.addEventListener('keydown',e=>{const input=e.target.closest('input,textarea,[contenteditable]');if(input||$('new-dialog').open)return;if(e.code==='Space'){space=true;e.preventDefault();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();travel(e.shiftKey?'redo':'undo');return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();travel('redo');return;}if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'){if(gesture)finish({pointerId:gesture.pointerId},true);select(null);chooseTool('select');}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}const t=toolInfo.find(t=>t[2].toLowerCase()===e.key.toLowerCase());if(t)chooseTool(t[0]);});
window.addEventListener('keyup',e=>{if(e.code==='Space')space=false;});window.addEventListener('blur',()=>{space=false;});window.addEventListener('pagehide',save);
$('backdrop').innerHTML=backdrop();chooseTool('select');renderAll();requestAnimationFrame(fit);new ResizeObserver(()=>{applyCamera();}).observe(svg);
save();
if(saveBlocked){toast('An existing save could not be read. It has been preserved. Export this world, or import a valid Atlas backup to resume saving.');}
